export function t(key, vars) {
  let s = (lang === 'fr' || lang === 'en' ? D[lang][key] : pack?.ui[key]) ?? D[lang === 'fr' ? 'fr' : 'en'][key] ?? D.fr[key] ?? key;
  if (vars) for (const k in vars) s = s.replaceAll(`{${k}}`, vars[k]);
  return s;
}
/** Pluriel : choisit `clé_one` ou `clé_other` selon Intl.PluralRules de la langue de l'app ({n} injecté ; repli sur la clé seule). */
let _pr = null, _prLoc = '';
export function plural(n) {
  const loc = locale();
  try { if (!_pr || _prLoc !== loc) { _pr = new Intl.PluralRules(loc); _prLoc = loc; } return _pr.select(+n || 0); } catch { return +n === 1 ? 'one' : 'other'; }
}
export function tp(key, n, vars) {
  const k = key + (plural(n) === 'one' ? '_one' : '_other');
  return t(t(k) === k ? key : k, { n, ...vars });
}
